INSERT INTO comments (id, image_url, name, comment, good, create_time) VALUES
(1,  'https://picsum.photos/seed/1/100/100',  '路过的风',     '无意间点进来的，没想到资源整理得这么全，收藏了！', 1, '2024-03-12 09:09:09'),
(2,  'https://picsum.photos/seed/2/100/100',  '深夜赶due人',  '凌晨三点还在找资料，感谢博主的汇总，救了大命了。', 1, '2024-03-12 10:15:30'),
(3,  'https://picsum.photos/seed/3/100/100',  '学Java的小王', '分类很清晰，找东西特别方便，比搜索引擎还好用。', 1, '2024-03-12 11:20:12'),
(4,  'https://picsum.photos/seed/4/100/100',  '前端萌新',     '请问博主这个网站是纯自己写的吗？用了什么技术栈？', 0, '2024-03-12 11:25:45'),
(5,  'https://picsum.photos/seed/5/100/100',  '毕业设计选手', '做毕设全靠这个站找资料，导师都夸我参考的文献质量高哈哈。', 1, '2024-03-12 14:00:00'),
(6,  'https://picsum.photos/seed/6/100/100',  '设计小美',     '网站界面看着真舒服，配色和排版都很用心，爱了。', 1, '2024-03-12 15:30:22'),
(7,  'https://picsum.photos/seed/7/100/100',  '考研党',       '考研复习的时候天天来刷，比翻书快多了。', 1, '2024-03-12 16:00:00'),
(8,  'https://picsum.photos/seed/8/100/100',  '摸鱼达人',     '上班偷偷看博客学技术，老板还以为我在认真查文档。', 1, '2024-03-12 16:10:00'),
(9,  'https://picsum.photos/seed/9/100/100',  '全干工程师',   '前后端资源都有，终于不用开十几个收藏夹了。', 1, '2024-03-12 16:20:00'),
(10, 'https://picsum.photos/seed/10/100/100', '转行小白',     '半路转行的，这个站帮我少走了好多弯路，感谢博主！', 1, '2024-03-12 16:30:00'),
(11, 'https://picsum.photos/seed/11/100/100', '产品小刘',     '建议加个搜索功能，资源多了之后找起来会更方便。', 0, '2024-03-12 16:40:00'),
(12, 'https://picsum.photos/seed/12/100/100', '运维老张',     '有没有考虑加一些运维和部署相关的资源？想偷师一下。', 0, '2024-03-12 16:50:00'),
(13, 'https://picsum.photos/seed/13/100/100', 'UI设计师',    '弹幕互动这个功能挺有意思的，第一次在资源站看到这种设计。', 1, '2024-03-12 17:00:00'),
(14, 'https://picsum.photos/seed/14/100/100', '实习生小李',   '刚入职啥也不会，全靠这个站充电，同事都以为我是老手。', 1, '2024-03-12 17:10:00'),
(15, 'https://picsum.photos/seed/15/100/100', '独立开发者',   '资源质量都很高，感觉博主是用心筛选过的，不是随便堆链接。', 1, '2024-03-12 17:20:00'),
(16, 'https://picsum.photos/seed/16/100/100', '大数据选手',   '数据相关的资源能再多一些吗？这块感觉还有拓展空间。', 1, '2024-03-12 17:30:00'),
(17, 'https://picsum.photos/seed/17/100/100', '在校研究生',   '写论文找参考资料的时候经常来逛，已经推荐给同门了。', 0, '2024-03-12 17:40:00'),
(18, 'https://picsum.photos/seed/18/100/100', '产品经理阿强', '我们团队的技术选型就是参考了这个站，省了好多调研时间。', 1, '2024-03-12 17:50:00'),
(19, 'https://picsum.photos/seed/19/100/100', '自由职业者',   '平时接单经常需要快速上手新技术，这个站简直是宝藏。', 1, '2024-03-12 18:00:00'),
(20, 'https://picsum.photos/seed/20/100/100', '代码洁癖',     '网站代码写得挺规范的，在 GitHub 上看过源码，学到了。', 1, '2024-03-12 18:10:00'),
(21, 'https://picsum.photos/seed/21/100/100', '技术博主同行', '同为技术博主，你的资源整理方式值得我学习，互相交流呀。', 1, '2024-03-12 18:20:00'),
(22, 'https://picsum.photos/seed/22/100/100', 'CTO老陈',     '已经把这个站加入新人入职手册了，省得我每次都重复讲一遍。', 1, '2024-03-12 18:30:00'),
(23, 'https://picsum.photos/seed/23/100/100', '算法爱好者',   '算法和面试相关的资源整理得太好了，刷题必备。', 1, '2024-03-12 18:40:00'),
(24, 'https://picsum.photos/seed/24/100/100', '开源贡献者',   '发现几个开源项目的链接，正好是我最近在关注的项目，缘分！', 1, '2024-03-12 18:50:00'),
(25, 'https://picsum.photos/seed/25/100/100', '培训班学员',   '培训机构的课程太贵了，还好有博主这种良心分享，致敬。', 1, '2024-03-12 19:00:00'),
(26, 'https://picsum.photos/seed/26/100/100', '手机党',       '手机端浏览体验也不错，通勤路上就能看，很方便。', 1, '2024-03-12 19:10:00'),
(27, 'https://picsum.photos/seed/27/100/100', '老访客',       '关注这个站好久了，看着一步步完善，博主加油更新！', 1, '2024-03-12 19:20:00'),
(28, 'https://picsum.photos/seed/28/100/100', '鹅厂实习生',   '面试前在这个站突击了一下，很多知识点都考到了，上岸了！', 1, '2024-03-12 19:30:00'),
(29, 'https://picsum.photos/seed/29/100/100', '挑刺大王',     '有几个链接好像失效了，博主有空可以检查更新一下。', 0, '2024-03-12 19:40:00'),
(30, 'https://picsum.photos/seed/30/100/100', '忠实粉丝',     '已经把网站推荐给整个技术群了，大家都说好，博主继续加油！', 1, '2024-03-12 19:50:00'),
(31, 'https://p3fx.kgimg.com/v2/fxuserlogo/eac9145ecd909b9606c4f8e5f3e936e7.jpg_200x200.jpg', '匿名用户', 'sdfsdfsd', 0, '2026-06-09 16:26:47'),
(32, 'https://p3fx.kgimg.com/v2/fxuserlogo/eac9145ecd909b9606c4f8e5f3e936e7.jpg_200x200.jpg', '匿名用户', 'sfwefwe', 0, '2026-06-09 16:27:20'),
(33, 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/pictures/ikun.jpg', '匿名用户', '45435的风格', 0, '2026-06-10 10:16:26');
