INSERT INTO books (id, name, author, introduction, cover, back_color) VALUES
(1,  '悲剧人偶',           '[日] 东野圭吾',           '日本作家东野圭吾1989年发表的长篇小说。小说采用双线叙事结构，主线讲述永岛为母复仇而策划的连环杀人案，辅以人偶视角见证竹宫家族三代恩怨。作品通过镜子戏法、指纹伪造等本格推理元素构建蛛网式谜题。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/1.jpg', NULL),
(2,  '背影的记忆',         '[日] 长岛有里枝',          '日本前卫摄影师及作家长岛有里枝的散文集，收录十三篇人生故事。作者以摄影与文字结合的方式，透过影像企图以"亲密"表达"疏离"与"孤独"，记录了成为母亲后不断回想起自己童年的点滴。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/2.jpg', NULL),
(3,  '巴黎圣母院',         '[法] 维克多·雨果',         '法国浪漫主义文学巨匠雨果于1831年创作的首部长篇小说。以15世纪路易十一统治时期的巴黎为背景，通过吉卜赛女郎爱斯梅拉达、敲钟人加西莫多等人的命运纠葛，展现教会与封建势力对民众的压迫。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/3.jpg', NULL),
(4,  '百年孤独',           '[哥伦比亚] 加西亚·马尔克斯', '拉丁美洲魔幻现实主义文学的代表作。故事讲述马孔多小镇和布恩迪亚家族的兴衰变化与传奇故事，记录了家族命运与百年历史，刻画人物孤独的灵魂与自我救赎。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/4.jpg', NULL),
(5,  '八十天环游世界',     '[法] 儒勒·凡尔纳',         '法国科幻作家凡尔纳的经典冒险小说。讲述了英国绅士福格先生与朋友打赌，要在80天内环游地球一周回到伦敦，途中经历了种种惊险奇遇的故事。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/5.jpg', NULL),
(6,  '白夜行',             '[日] 东野圭吾',           '日本作家东野圭吾创作的长篇推理小说，1999年首次出版。小说以一场发生在废旧楼房的谋杀案开篇，讲述了主人公桐原亮司和唐泽雪穗从天真稚嫩走向犯罪迷途，最终将灵魂埋葬于黑暗深渊的故事。作品深入剖析人性、原生家庭等现实问题，曾入围第122届直木奖，简体中文版发行量超600万册。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/6.jpg', '#7b9eeb'),
(7,  '幻夜',               '[日] 东野圭吾',           '被视为《白夜行》姊妹篇的长篇小说。故事围绕地震后水原雅也杀舅被神秘女子目击展开，两人前往东京后陷入无边幻夜，所有接近她的人皆遭厄运，被誉为"绝望之书"。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/7.jpg', NULL),
(8,  '活着',               '余华',                    '中国当代作家余华的代表作。通过主人公福贵从地主少爷到贫农的命运转折，展现其历经家产败光、战争动荡、亲人相继离世等磨难，最终与老牛相依为命的故事，探讨了生存的意义。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/8.jpg', NULL),
(9,  '彷徨之刃',           '[日] 东野圭吾',           '日本作家东野圭吾创作的长篇小说，首次出版于2004年12月。小说讲述了与女儿相依为命的父亲长峰重树，在女儿被两个未成年人凌虐杀害后，为复仇而成为被通缉的杀人犯的故事。作品探讨未成年人犯罪的法律保护与情感之间的悖论，引发读者对社会法律体系的讨论。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/9.jpg', NULL),
(10, '分身',               '[日] 东野圭吾',           '日本作家东野圭吾创作的科幻小说兼悬疑推理长篇小说，首版于1993年。主角是两位外貌酷似的女孩鞠子和双叶，围绕二人出生的秘密产生各种难解谜题，见不得光的滥用医疗技术事件和二十年前的爱恨纠葛渐渐浮出水面。作品采用双线叙述方法，从不同角度逐步揭开真相。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/10.jpg', NULL),
(11, '放学后',             '[日] 东野圭吾',           '日本作家东野圭吾的成名作，获第31届江户川乱步奖。小说以校园为背景，讲述教师前岛在学生的帮助下破解密室杀人案的故事，融合了本格推理与青春元素。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/11.jpg', NULL),
(12, '幻夜',               '[日] 东野圭吾',           '被视为《白夜行》姊妹篇的长篇小说。故事围绕地震后水原雅也杀舅被神秘女子目击展开，两人前往东京后陷入无边幻夜，所有接近她的人皆遭厄运，被誉为"绝望之书"。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/12.jpg', NULL),
(13, '活着',               '余华',                    '中国当代作家余华的代表作。通过主人公福贵从地主少爷到贫农的命运转折，展现其历经家产败光、战争动荡、亲人相继离世等磨难，最终与老牛相依为命的故事，探讨了生存的意义。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/13.jpg', NULL),
(14, '简·爱',              '[英] 夏洛蒂·勃朗特',      '具有自传色彩的英国经典小说，1847年首次出版。讲述孤女简·爱自幼受虐，后成为家庭教师，与主人罗切斯特相爱，发现其有疯妻后离开，继承遗产后重返故地与失明的罗切斯特终成眷属的故事。作品展现女性独立与反抗精神。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/14.jpg', NULL),
(15, '解忧杂货铺',         '[日] 东野圭吾',           '东野圭吾的非推理类代表作。讲述一家能解决烦恼的杂货店，通过信件往来连接过去与现在，帮助人们找到人生答案。作品温暖治愈，全球销量极高。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/15.jpg', NULL),
(16, '鲁滨孙漂流记',       '[英] 丹尼尔·笛福',       '英国现实主义小说奠基之作。讲述鲁滨逊·克鲁索在荒岛上凭借强韧意志生存28年多，最终返回故乡的故事，歌颂了人的智慧与勤劳。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/16.jpg', NULL),
(17, '飘',                 '[美] 玛格丽特·米切尔',    '美国女作家玛格丽特·米切尔创作的长篇小说。以美国南北战争为背景，描写了斯嘉丽·奥哈拉在战争废墟中重建家园的奋斗历程，展现了女性在乱世中的坚韧与成长。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/17.jpg', NULL),
(18, '圣女的救济',         '[日] 东野圭吾',           '神探伽利略系列作品之一。讲述了真柴义之在家中离奇死亡，看似完美的不在场证明背后隐藏着巨大的阴谋，汤川学通过科学逻辑揭开了这起"虚数解"般的犯罪手法。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/18.jpg', NULL),
(19, '我杀了他',           '[日] 东野圭吾',           '加贺恭一郎系列作品。新娘在婚礼前夕被发现死于家中，现场有三个嫌疑人，每个人都声称"我杀了她/他"。加贺恭一郎需要通过细节推理找出真正的凶手。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/19.jpg', NULL),
(20, '未知的探索',         '王艾米 / 李子',           '一本关于封面设计的书籍或作品集，由艾米出版于2022年8月16日至22日期间推出。内容可能涉及设计灵感、创意过程或行业趋势，旨在鼓励读者在设计领域进行未知领域的探索与创新。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/20.jpg', NULL),
(21, '信',                 '[日] 东野圭吾',           '一部探讨犯罪者家属社会处境的深刻小说。讲述了刚志为了弟弟直贵的学费去盗窃，却意外杀人入狱。出狱后，兄弟俩因"杀人犯家属"的身份在社会上遭受歧视与排斥，展现了人性的挣扎与社会的冷漠。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/21.jpg', NULL),
(22, '新参者',             '[日] 东野圭吾',           '加贺恭一郎系列巅峰之作。发生在日本桥人形町的一起杀人案，加贺通过走访街区内的仙贝店、料亭、钟表店等，在解开案件谜团的同时，也抚慰了街坊邻居们心中的创伤与秘密。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/22.jpg', NULL),
(23, '哈姆雷特',           '[英] 威廉·莎士比亚',      '莎士比亚最著名的悲剧作品。讲述了丹麦王子哈姆雷特为父报仇，与篡位的叔父克劳狄斯进行斗争，最终导致包括自己在内的多人死亡的悲剧故事，探讨了生存与毁灭的哲学命题。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/23.jpg', NULL),
(24, '堂·吉诃德',          '[西] 塞万提斯',           '西班牙文学的巅峰之作。讲述了沉迷骑士小说的乡绅阿隆索·吉哈诺自封为"堂·吉诃德"，骑着瘦马、带着侍从桑丘四处游侠，闹出无数笑话却又充满理想主义色彩的故事。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/24.jpg', NULL),
(25, '呼兰河传',           '萧红',                    '中国现代女作家萧红的回忆性长篇小说。通过对故乡呼兰河小城的风土人情、人物命运的描写，展现了旧时代东北农村愚昧、落后的一面，同时也流露出对童年生活的眷恋。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/25.jpg', NULL),
(26, '西游记',             '[明] 吴承恩',             '中国古代第一部浪漫主义章回体长篇神魔小说。讲述了唐僧师徒四人西天取经，一路上降妖除魔，历经九九八十一难，最终取得真经修成正果的故事。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/26.jpg', NULL),
(27, '一只猫的前世今生',   '[日] 高小定',             '日本作家高小定所著的哲思散文集，副标题为"吾是猫：一只猫的日常与哲学"，由王小天翻译，稿定教育出版。该书以猫的视角展开叙述，融合日常观察与哲学思辨，探讨生命、存在与人与动物的关系。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/27.jpg', NULL),
(28, '白鹿原',             '陈忠实',                  '中国当代作家陈忠实历时六年创作的长篇小说，1993年首次出版。小说以陕西关中地区白鹿原上白鹿村为缩影，通过白、鹿两大家族祖孙三代的恩怨纷争，展现了从清朝末年到二十世纪七八十年代长达半个多世纪的历史变迁。作品深刻反映了中国百姓从封建社会到民主社会的转型阵痛，被誉为"民族秘史"，荣获第四届茅盾文学奖，并被改编为电影、电视剧、话剧等多种艺术形式。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/28.jpg', '#f06aa2'),
(29, '额尔古纳河右岸',     '迟子建',                  '中国当代作家迟子建创作的长篇小说，2005年首次出版。小说以一位年近九旬的鄂温克族最后一位女酋长的自述口吻，讲述了这个弱小民族在额尔古纳河右岸森林中顽强抗争与优美爱情的百年沧桑。作品语言精妙，融合了现实主义与自然主义、童话与神话，被誉为"一部苍凉的挽歌"，荣获第七届茅盾文学奖，入选"新中国70年70部长篇小说典藏"。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/29.jpg', '#eba25e'),
(30, '摆渡人',             '[英]克莱儿·麦克福尔',     '《摆渡人》是英国作家克莱儿·麦克福尔创作的长篇小说，讲述了15岁女孩迪伦在火车事故中丧生后，灵魂进入生死之间的"荒原"，与她的灵魂摆渡人崔斯坦相遇并共同穿越险境的故事。小说通过奇幻旅程探讨了爱、勇气、自我成长与命运选择等深刻主题，被誉为心灵治愈与人性救赎之作，全球销量超千万册，畅销欧美33个国家。', 'https://sky-lkc.oss-cn-beijing.aliyuncs.com/picture/book/30.jpg', NULL);
